import{_ as r,o as a,c as o,aO as n}from"./chunks/framework.BFrk9dwu.js";const i="/travel/hongkong.jpg",e="/travel/hongkong/tst-avenue-1.jpg",s="/travel/hongkong/ferry-1.jpg",g="/travel/hongkong/central-midlevels-1.jpg",l="/travel/hongkong/central-street-1.jpg",d="/travel/hongkong/peak-sunset-1.jpg",p="/travel/hongkong/peak-night-1.jpg",h="/travel/hongkong/food-roast-1.jpg",c="/travel/hongkong/food-noodle-1.jpg",x=JSON.parse('{"title":"香港：一天走完海、山和旧街","description":"香港一日游：尖沙咀维港、天星小轮过海、中环老街、太平山顶日落，附交通、吃什么、注意事项与花费","frontmatter":{"title":"香港：一天走完海、山和旧街","date":"2026-11-27T20:20:00.000Z","description":"香港一日游：尖沙咀维港、天星小轮过海、中环老街、太平山顶日落，附交通、吃什么、注意事项与花费","categories":["life","travel"],"permalink":"/pages/cadfcd"},"headers":[],"relativePath":"life/travel/hongkong.md","filePath":"life/travel/hongkong.md","lastUpdated":1795783584000}'),f={name:"life/travel/hongkong.md"};function u(m,t,_,v,b,k){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="香港-一天走完海、山和旧街" tabindex="-1">香港：一天走完海、山和旧街 <a class="header-anchor" href="#香港-一天走完海、山和旧街" aria-label="Permalink to &quot;香港：一天走完海、山和旧街&quot;">​</a></h1><div class="travel-hero"><img src="'+i+'" alt="从太平山顶俯瞰维多利亚港的黄昏：摩天楼密集，海面泛着暮色的光"></div><p>香港一天能玩得挺完整，前提是不贪。海、山、旧街这三样摆在一起，中间只隔一趟轮渡或一站地铁，走顺了不累。</p><p>早上从广州南出发，五十多分钟就到西九龙；晚上十点多的车回，一天刚好。</p><h2 id="怎么去" tabindex="-1">怎么去 <a class="header-anchor" href="#怎么去" aria-label="Permalink to &quot;怎么去&quot;">​</a></h2><ul><li><strong>高铁</strong>：广州南到西九龙，二等座 215 元，最快四十七分钟，早班六点半前后。这是最省事的方式，直接落在市区。</li><li><strong>从深圳过关</strong>：福田、罗湖都能过，先坐高铁或动车到深圳，再换地铁过关，路费省一半，但多花两小时。</li><li><strong>站内通关</strong>：西九龙是&quot;一地两检&quot;，出境入境都在站里办，<strong>提前四十五分钟到站</strong>，别掐点。</li><li><strong>城内</strong>：地铁最便宜也最快，一两站就是四五港币；叮叮车三块，天星小轮五块。办张八达通，充一百多港币够一天。</li></ul><h2 id="一日怎么走" tabindex="-1">一日怎么走 <a class="header-anchor" href="#一日怎么走" aria-label="Permalink to &quot;一日怎么走&quot;">​</a></h2><h3 id="上午-·-尖沙咀-先看海" tabindex="-1">上午 · 尖沙咀，先看海 <a class="header-anchor" href="#上午-·-尖沙咀-先看海" aria-label="Permalink to &quot;上午 · 尖沙咀，先看海&quot;">​</a></h3><p>出站后从柯士甸站坐一站到尖东，或者干脆走十五分钟。<strong>星光大道</strong>沿着海边铺开，对岸就是港岛那排摩天楼，早上的光顺，人也少。</p><div class="travel-photo"><img src="'+e+'" alt="尖沙咀星光大道：木栈道沿维港延伸，对岸是港岛摩天楼天际线，几位游客在慢走"><figcaption>星光大道：这一排楼，白天和晚上是两张脸</figcaption></div><p>再往里走是<strong>香港艺术馆</strong>，免费，落地窗前能坐着看海，歇一脚正好。<strong>周四闭馆</strong>，其余日子十点开门。</p><h3 id="中午-·-坐天星小轮过海" tabindex="-1">中午 · 坐天星小轮过海 <a class="header-anchor" href="#中午-·-坐天星小轮过海" aria-label="Permalink to &quot;中午 · 坐天星小轮过海&quot;">​</a></h3><p>从星光大道走到天星码头，投五块钱上船。绿色船身、木座椅，一百多年没怎么变。上层人少，风景开阔，十来分钟就横过维港——这是全香港最便宜的一段海景。</p><figure class="travel-photo"><img src="'+s+'" alt="天星小轮在维港中航行：绿白双色船身，船头破开水面，背景是中环一带的楼群"><figcaption>天星小轮：五块钱，横过维多利亚港</figcaption></figure><p>下船就是中环。午饭放在上船前更顺——在佐敦一带吃碗云吞面，再走回码头，比在中环排队省时间。</p><h3 id="下午-·-中环的旧街" tabindex="-1">下午 · 中环的旧街 <a class="header-anchor" href="#下午-·-中环的旧街" aria-label="Permalink to &quot;下午 · 中环的旧街&quot;">​</a></h3><p>中环好看的地方不在商场，在坡上。<strong>中环街市</strong>进去转一圈，然后顺着<strong>半山扶梯</strong>往上，两侧是几十年的唐楼、铁闸门小店、斑驳的墙。</p><div class="travel-grid"><figure><img src="'+g+'" alt="中环半山自动扶梯：狭窄街道里长长的户外扶梯向上，两侧是老旧唐楼和小店"><figcaption>半山扶梯，一路往上都是老香港</figcaption></figure><figure><img src="'+l+'" alt="中环石板街：湿漉漉的石阶向下延伸，两侧是摊档和老建筑，路灯将亮"><figcaption>石板街，石头被踩得发亮</figcaption></figure></div><p>下来绕到<strong>石板街</strong>（砵典乍街），再往上是荷李活道、PMQ 一带。这一片不用赶，慢慢走两小时，比打卡十个点值。</p><h3 id="傍晚-·-太平山顶等日落" tabindex="-1">傍晚 · 太平山顶等日落 <a class="header-anchor" href="#傍晚-·-太平山顶等日落" aria-label="Permalink to &quot;傍晚 · 太平山顶等日落&quot;">​</a></h3><p>从中环六号码头坐 <strong>15 路巴士</strong>上山顶，四十分钟，一路上能看见楼越来越矮、海越来越宽。也可以坐缆车，但下午排队常要半小时以上。</p><p>到山顶先去<strong>卢吉道</strong>——免费的观景步道，走二十分钟就到开阔处，视野比凌霄阁还宽。</p><figure class="travel-photo"><img src="'+d+'" alt="太平山卢吉道：从半山步道望向维港和港岛，夕阳压在城市楼群上"><figcaption>卢吉道：免费，人少，看的是同一个海</figcaption></figure><p>太阳落下去大约是五点四十。想再高一点就上<strong>凌霄阁摩天台</strong>，等天色转蓝，城市开始亮灯。</p><h3 id="晚上-·-灯海-然后回程" tabindex="-1">晚上 · 灯海，然后回程 <a class="header-anchor" href="#晚上-·-灯海-然后回程" aria-label="Permalink to &quot;晚上 · 灯海，然后回程&quot;">​</a></h3><figure class="travel-photo"><img src="'+p+'" alt="从太平山凌霄阁俯瞰香港夜景：城市灯海一直铺到海边，维港两岸灯火通明"><figcaption>灯亮起来之后，才明白香港为什么建在山上</figcaption></figure><p>下山别硬等缆车，<strong>15 路巴士</strong>一样回中环，还不用排队。七点多吃晚饭，然后坐叮叮车晃两站，或者再坐一趟天星小轮回尖沙咀，在海边走到九点一刻。</p><p>九点二十回到西九龙站，赶 <strong>22:11</strong> 那班车，23:14 到广州南。回程过关加安检，留足四十五分钟。</p><p><strong>注意</strong>：以前每晚八点的&quot;幻彩咏香江&quot;已经在 2026 年 11 月 18 日演完停办，新的光影项目还没定时间。别按老攻略掐着点去等，两岸的楼照旧亮着，夜景本身没变。</p><h2 id="吃什么" tabindex="-1">吃什么 <a class="header-anchor" href="#吃什么" aria-label="Permalink to &quot;吃什么&quot;">​</a></h2><p>港式一天不用吃很多顿，但每一顿要吃对地方。</p><table tabindex="0"><thead><tr><th>吃什么</th><th>去哪吃</th><th>说明</th></tr></thead><tbody><tr><td>云吞面</td><td>佐敦、中环一带老面店</td><td>四十块上下，虾要弹、汤要清，面是竹升压的</td></tr><tr><td>烧鹅</td><td>中环威灵顿街一带</td><td>点鹅腿，最快卖完；皮脆油香，不用蘸汁</td></tr><tr><td>丝袜奶茶 + 菠萝油</td><td>中环摆花街、结志街</td><td>下午三四点那一顿，站着喝也地道</td></tr><tr><td>炒蛋多士</td><td>佐敦</td><td>本地人的早饭，蛋要嫩</td></tr><tr><td>蛋挞</td><td>中环老饼家</td><td>牛油皮、蛋心晃，出炉的时候最好</td></tr><tr><td>煲仔饭</td><td>庙街</td><td>走替代路线才吃得上，饭焦是精华</td></tr></tbody></table><div class="travel-grid"><figure><img src="'+h+'" alt="港式烧鹅饭：白瓷碟里切好的烧鹅腿，皮色深红油亮，配白饭和酸梅酱"><figcaption>烧鹅腿，皮是脆的，油是香的</figcaption></figure><figure><img src="'+c+'" alt="港式云吞面：青花瓷碗里细长的竹升面，几只虾云吞沉在碗底，清汤"><figcaption>云吞面：一碗四十块，香港最日常的一餐</figcaption></figure></div><p><strong>留个心</strong>：香港不少老店有固定休息日，很多挑周日或周四，还有的只收现金。出发当天用 OpenRice 搜一下店名，看一眼当天开不开门再去，比照着攻略直接上门稳妥。</p><h2 id="花费" tabindex="-1">花费 <a class="header-anchor" href="#花费" aria-label="Permalink to &quot;花费&quot;">​</a></h2><p>一个人，从广州出发，一天来回：</p><table tabindex="0"><thead><tr><th>项目</th><th>金额</th></tr></thead><tbody><tr><td>高铁往返（广州南↔西九龙）</td><td>430 元</td></tr><tr><td>香港交通（地铁、巴士、叮叮车、轮渡）</td><td>60–90 港币</td></tr><tr><td>山顶缆车（来回 / 含凌霄阁套票）</td><td>116–182 港币</td></tr><tr><td>吃饭（两餐正餐 + 下午茶 + 小吃）</td><td>250–350 港币</td></tr><tr><td>流量、寄存或买点手信</td><td>50–100 港币</td></tr><tr><td><strong>合计</strong></td><td><strong>约 900–1100 元</strong></td></tr></tbody></table><p>香港境内大概五百到七百港币，按一比零点九二折算。多数地方能扫码，但<strong>八达通最稳</strong>；带两三百港币现金，给只收现金的店。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li><strong>签注先查</strong>。通行证背面要有有效签注。团队旅游（L）签现在也不用跟团、不用送关，可以自己直接过关，和自由行没差别。</li><li><strong>高铁票提前买</strong>。周末早班容易满，12306 实名购票，别指望到站再补。</li><li><strong>提前四十五分钟到西九龙站</strong>。出入境都在站内，早上和傍晚排队都长。</li><li><strong>香港艺术馆周四闭馆</strong>，其余日子十点开门，免费。</li><li><strong>山顶缆车网上先买票</strong>，现场买票和上车是两条队；不想排就坐 15 路巴士。</li><li><strong>别按老攻略等八点的灯光秀</strong>，那场已经停办了。</li><li><strong>穿薄一点，带件外套</strong>。十二月白天十几到二十度出头，走一天会出汗，海边早晚有风。</li><li><strong>流量提前买</strong>。过关前买好一日包或 eSIM，地图和查店全靠它。</li><li><strong>鞋</strong>。这一天两万步起步，山顶还有一段坡，别穿新鞋。</li><li><strong>回程别赌末班车</strong>。西九龙到广州南末班在 22:37 左右，赶不上就只能改签或者睡香港。</li></ul><p><a href="/life/travel/">← 回旅游攻略</a></p>',41)])])}const P=r(f,[["render",u]]);export{x as __pageData,P as default};
